<option value="{{ $opcionPersonal['rut'] }}" @selected($opcionSeleccionada) data-estamento="{{ $opcionPersonal['estamento'] }}" data-fase-plan="{{ $fasePersonal }}" data-nombre="{{ $opcionPersonal['nombre'] }}" data-rut="{{ $opcionPersonal['rut'] }}" data-titulo="{{ $opcionPersonal['titulo'] }}" data-funcion="{{ $opcionPersonal['funcion'] }}" data-prioridad="{{ $opcionPersonal['prioridad'] }}" data-prioridad-label="{{ $opcionPersonal['prioridad_label'] }}" data-antiguedad="{{ $opcionPersonal['antiguedad'] }}" data-titular-disponible="{{ $fmt($opcionPersonal['titular_disponible']) }}" data-contrata-disponible="{{ $fmt($opcionPersonal['contrata_disponible']) }}">{{ $fasePersonal === null ? $opcionPersonal['label'] : $opcionPersonal['nombre'].' · '.$opcionPersonal['rut'].' · Título: '.$opcionPersonal['titulo'].' · '.$opcionPersonal['prioridad_label'].' · Disponible '.($fasePersonal === 'titular' ? 'titular: '.$fmt($opcionPersonal['titular_disponible']) : 'a contrata: '.$fmt($opcionPersonal['contrata_disponible'])).' h' }}</option>
